package com.honorablemobile

import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.annotation.Config
import android.net.Uri
import android.content.Intent
import android.app.Activity
import app.honorable.editor.PhotoPresetNamespace
import app.honorable.editor.EditorAccessMode
import org.junit.Assert.*
import org.junit.Test
@RunWith(RobolectricTestRunner::class)
@Config(sdk = [34], manifest = Config.NONE, application = android.app.Application::class)
class VideoSaveRequestTest {
 private val unsafe=JvmTestAllocator
 private fun set(a:Any,n:String,v:Any?)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.set(a,v)
 private fun get(a:Any,n:String)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.get(a)
 private fun call(a:Any,n:String,vararg args:Any?)=a.javaClass.declaredMethods.single{it.name==n&&it.parameterCount==args.size}.apply{isAccessible=true}.invoke(a,*args)
 private fun activity()=(unsafe.allocateInstance(HonorableVideoEditorActivity::class.java)as HonorableVideoEditorActivity).also{set(it,"project",VideoEditProject(5000));set(it,"source",Uri.parse("content://synthetic/video"));set(it,"primaryDurationMs",5000L);set(it,"durationMs",5000);set(it,"accessMode",EditorAccessMode.GUEST_BASIC);set(it,"workspaceActive",true);set(it,"importedSources",linkedMapOf<String,VideoSource>())}
 @Test fun pausedExportEntryReturnsBeforeUninitializedWidgets(){val a=activity();set(a,"workspaceActive",false);call(a,"saveCopy");assertNull(get(a,"pendingRange"))}

 private val destination=Uri.parse("content://synthetic/output")
 @Suppress("UNCHECKED_CAST") private fun request(a:HonorableVideoEditorActivity,code:Int=1000):VideoSaveRequest {
  set(a,"pendingRange",0L to 5000L);val p=get(a,"project")as VideoEditProject
  return VideoSaveRequest(code,call(a,"closeState")as VideoCloseState,EditorAccessMode.GUEST_BASIC,PhotoPresetNamespace.GUEST,p.segments,p.soundtrack,call(a,"sourceUris")as Map<String,Uri>,call(a,"sourceDurations")as Map<String,Long>,get(a,"importedSources")as Map<String,VideoSource>).also{set(a,"videoSaveRequest",it)}
 }
 private fun result(uri:Uri=destination)=Intent().setData(uri)
 private fun accept(a:HonorableVideoEditorActivity,code:Int=1000,ok:Int=Activity.RESULT_OK,data:Intent?=result())=call(a,"acceptVideoSaveResult",code,ok,data)
 private fun ready(a:HonorableVideoEditorActivity,code:Int=1000)=request(a,code).also{set(a,"workspaceActive",false);accept(a,code)}
 private fun rejected(action:()->Unit){try{action();fail("Expected invalid code rejection")}catch(_:IllegalArgumentException){}}
 @Test fun snapshotsDefensivelyFreezeClipsCaptionListsMapsAndMusic(){val a=activity();val p=get(a,"project")as VideoEditProject;val cues=mutableListOf(VideoCaption(0,500,"Keep"));val clips=mutableListOf(VideoSegment(0,5000,captions=cues));val sources=mutableMapOf("primary" to Uri.parse("content://synthetic/video"));val durations=mutableMapOf("primary" to 5000L);val catalog=mutableMapOf("extra" to VideoSource("extra","content://synthetic/extra",7000));val music=VideoSoundtrack("content://synthetic/music",10000,loop=false);val r=VideoSaveRequest(1000,VideoCloseState.capture(p,5000,0,null,null,true,false,"content://synthetic/video"),EditorAccessMode.GUEST_BASIC,PhotoPresetNamespace.GUEST,clips,music,sources,durations,catalog);clips.clear();cues.clear();sources.clear();durations.clear();catalog.clear();assertEquals("Keep",r.clips.single().captions.single().text);assertEquals(1,r.sources.size);assertEquals(5000L,r.durations["primary"]);assertSame(music,r.music)}
 @Test fun returnedDestinationIsSingleUseAndNeverReplacedByDuplicate(){val r=request(activity());assertTrue(r.accept(1000,true,destination));assertTrue(r.isReady);assertFalse(r.accept(1000,true,Uri.parse("content://synthetic/other")));assertEquals(destination,r.beginWriting())}
 @Test fun wrongRequestCodeCannotConsumePicker(){val r=request(activity());assertFalse(r.accept(1001,true,destination));assertTrue(r.isPending);assertTrue(r.accept(1000,true,destination))}
 @Test fun cancelledMissingMalformedAndOriginalDestinationsCloseWithoutWriting(){for(uri in listOf<Uri?>(null,Uri.parse("file:///output"),Uri.parse("content:///no-authority"),Uri.parse("content://synthetic/video"))){val r=request(activity());assertTrue(r.accept(1000,true,uri));assertTrue(r.isClosed);assertNull(r.beginWriting())};val cancel=request(activity());assertTrue(cancel.accept(1000,false,destination));assertTrue(cancel.isClosed)}
 @Test fun writingCanBeClaimedOnlyOnce(){val r=request(activity());assertNull(r.beginWriting());r.accept(1000,true,destination);assertEquals(destination,r.beginWriting());assertTrue(r.isWriting);assertNull(r.beginWriting());assertFalse(r.accept(1000,true,destination))}
 @Test fun closedRequestCannotReviveOrConsumeLaterResults(){val r=request(activity());r.accept(1000,true,destination);r.close();r.close();assertTrue(r.isClosed);assertFalse(r.accept(1000,true,destination));assertNull(r.beginWriting())}
 @Suppress("UNCHECKED_CAST") @Test fun matchingChecksFullStateModeNamespaceAndProtectedCatalogs(){val a=activity();val r=request(a);val state=call(a,"closeState")as VideoCloseState;val uris=call(a,"sourceUris")as Map<String,Uri>;val durations=call(a,"sourceDurations")as Map<String,Long>;assertTrue(r.matches(state,EditorAccessMode.GUEST_BASIC,PhotoPresetNamespace.GUEST,uris,durations,emptyMap()));assertFalse(r.matches(state,EditorAccessMode.ACCOUNT,PhotoPresetNamespace.GUEST,uris,durations,emptyMap()));assertFalse(r.matches(state,EditorAccessMode.GUEST_BASIC,"another",uris,durations,emptyMap()));assertFalse(r.matches(state,EditorAccessMode.GUEST_BASIC,PhotoPresetNamespace.GUEST,uris+mapOf("extra" to destination),durations,emptyMap()));assertFalse(r.matches(state,EditorAccessMode.GUEST_BASIC,PhotoPresetNamespace.GUEST,uris,durations+mapOf("primary" to 6000L),emptyMap()));assertFalse(r.matches(state,EditorAccessMode.GUEST_BASIC,PhotoPresetNamespace.GUEST,uris,durations,mapOf("extra" to VideoSource("extra","content://synthetic/extra",7000))))}
 @Test fun exportRangePreparationDoesNotEditOrCreateUndo(){val a=activity();val p=get(a,"project")as VideoEditProject;val original=p.segments;val prepared=VideoExportSnapshot.clips(original,0,1000,3000);val r=VideoSaveRequest(1000,VideoCloseState.capture(p,5000,0,1000,3000,true,false,"content://synthetic/video"),EditorAccessMode.GUEST_BASIC,PhotoPresetNamespace.GUEST,prepared,null,mapOf("primary" to Uri.parse("content://synthetic/video")),mapOf("primary" to 5000L),emptyMap());assertSame(original,p.segments);assertFalse(p.canUndo);assertEquals(1000L,r.clips[0].startMs);assertEquals(3000L,r.clips[0].endMs)}
 @Test fun requestCodeBoundsAreReservedAndChecked(){assertTrue(VideoSaveRequest.ownsCode(1000));assertTrue(VideoSaveRequest.ownsCode(65535));for(code in listOf(22,29,999,65536))assertFalse(VideoSaveRequest.ownsCode(code));val a=activity();rejected{request(a,999)};rejected{request(a,65536)}}
 @Test fun activityAllocatesUniqueCodesAndStopsBeforeOverflow(){val a=activity();set(a,"nextVideoSaveCode",1000);assertEquals(1000,call(a,"allocateVideoSaveCode"));assertEquals(1001,call(a,"allocateVideoSaveCode"));set(a,"nextVideoSaveCode",65535);assertEquals(65535,call(a,"allocateVideoSaveCode"));try{call(a,"allocateVideoSaveCode");fail("Reused code")}catch(e:java.lang.reflect.InvocationTargetException){assertTrue(e.cause is IllegalArgumentException)};assertEquals(65536,get(a,"nextVideoSaveCode"))}
 @Test fun pausedResultStoresOnlyMetadataUntilForeground(){val a=activity();val r=ready(a);assertTrue(r.isReady);assertEquals(false,get(a,"saving"));assertSame(r,get(a,"videoSaveRequest"));assertEquals(false,call(a,"canDispatchVideoSave",r));call(a,"resumeVideoSave");assertTrue(r.isReady);set(a,"workspaceActive",true);assertEquals(true,call(a,"canDispatchVideoSave",r))}
 @Test fun pausedPickerCancellationReleasesOnlyItsOwnMarkers(){val a=activity();val r=request(a);set(a,"workspaceActive",false);accept(a,ok=Activity.RESULT_CANCELED,data=null);assertTrue(r.isClosed);assertNull(get(a,"videoSaveRequest"));assertNull(get(a,"pendingRange"));assertEquals(false,get(a,"saving"))}
 @Test fun changedSourceProjectMusicOrRecoveryDropsReadyResultBeforeProvider(){for(flag in listOf("source","duration","mode","project","music","recovery","busy","catalog")){val a=activity();val r=ready(a);val p=get(a,"project")as VideoEditProject;when(flag){"source"->set(a,"source",Uri.parse("content://synthetic/other"));"duration"->set(a,"primaryDurationMs",6000L);"mode"->set(a,"accessMode",EditorAccessMode.ACCOUNT);"project"->set(a,"project",VideoEditProject(5000));"music"->p.setSoundtrack(VideoSoundtrack("content://synthetic/music",10000));"recovery"->set(a,"recoveryBytes",byteArrayOf(1));"busy"->set(a,"importing",true);else->set(a,"importedSources",linkedMapOf("extra" to VideoSource("extra","content://synthetic/extra",7000)))};set(a,"workspaceActive",true);call(a,"resumeVideoSave");assertTrue(flag,r.isClosed);assertNull(get(a,"videoSaveRequest"));assertEquals(false,get(a,"saving"))}}
 @Test fun duplicateResultDoesNotReleaseOrReplaceCurrentReadyRequest(){val a=activity();val r=ready(a);accept(a,data=result(Uri.parse("content://synthetic/other")));assertSame(r,get(a,"videoSaveRequest"));assertTrue(r.isReady);assertEquals(destination,r.beginWriting())}
 @Test fun foreignOldResultCannotConsumeOrReleaseNewRequest(){val a=activity();set(a,"workspaceActive",false);val r=request(a,1001);accept(a,1000);assertTrue(r.isPending);assertSame(r,get(a,"videoSaveRequest"));for(code in 22..29)assertEquals(false,call(a,"allowsMediaImportResult",code));assertEquals(false,call(a,"allowsMediaImportResult",1000));assertEquals(true,call(a,"allowsMediaImportResult",1001));assertEquals(true,call(a,"allowsMediaImportResult",99))}
 @Test fun staleReleaseCannotUnlockOrClearNewWritingOwner(){val a=activity();val old=ready(a,1000);val current=request(a,1001);current.accept(1001,true,destination);current.beginWriting();set(a,"saving",true);assertEquals(false,call(a,"releaseVideoSave",old));assertSame(current,get(a,"videoSaveRequest"));assertEquals(true,get(a,"saving"));assertNotNull(get(a,"pendingRange"))}
 @Test fun currentWritingReleaseClearsItsOwnBusyStateOnce(){val a=activity();val r=ready(a);r.beginWriting();set(a,"saving",true);assertEquals(true,call(a,"releaseVideoSave",r));assertNull(get(a,"videoSaveRequest"));assertNull(get(a,"pendingRange"));assertEquals(false,get(a,"saving"));assertEquals(false,call(a,"releaseVideoSave",r))}
 @Test fun ownerlessReceiptCannotClearAnotherOperationsFlags(){val a=activity();set(a,"workspaceActive",false);set(a,"nextVideoSaveCode",1002);set(a,"importing",true);set(a,"pendingRange",1000L to 2000L);accept(a,1000);assertEquals(true,get(a,"importing"));assertEquals(1000L to 2000L,get(a,"pendingRange"));assertEquals(false,get(a,"saving"));assertEquals(false,get(a,"interruptedVideoSave"))}
 @Test fun expectedPickerPauseDoesNotUseDialogGenerationAsCancellation(){val a=activity();val r=ready(a);call(a,"invalidateCaptionReviews");assertTrue(r.isReady);set(a,"workspaceActive",true);assertEquals(true,call(a,"canDispatchVideoSave",r));assertEquals(false,get(a,"saving"))}
 @Test fun restoredPickerCodeIsNotReusedAndItsReceiptIsConsumedOnce(){val a=activity();set(a,"nextVideoSaveCode",1000);val code=call(a,"allocateVideoSaveCode")as Int;request(a,code);val state=android.os.Bundle();call(a,"writeVideoSaveState",state);val restored=activity();set(restored,"workspaceActive",false);call(restored,"restoreVideoSaveState",state);assertNull(get(restored,"videoSaveRequest"));assertEquals(1001,call(restored,"allocateVideoSaveCode"));assertEquals(1000,get(restored,"interruptedVideoSaveCode"));accept(restored,1000);assertEquals(true,get(restored,"interruptedVideoSave"));assertNull(get(restored,"interruptedVideoSaveCode"));set(restored,"interruptedVideoSave",false);accept(restored,1000);assertEquals(false,get(restored,"interruptedVideoSave"));assertEquals(false,get(restored,"saving"))}
 @Test fun restoredReturnedDestinationNeverRestartsExportOrPersistsUri(){val a=activity();set(a,"nextVideoSaveCode",1001);ready(a);val state=android.os.Bundle();call(a,"writeVideoSaveState",state);assertEquals(setOf("nextVideoSaveCode","videoSaveRequestCode","videoSaveHadDestination"),state.keySet());val restored=activity();call(restored,"restoreVideoSaveState",state);assertEquals(true,get(restored,"interruptedVideoSave"));assertNull(get(restored,"interruptedVideoSaveCode"));assertNull(get(restored,"videoSaveRequest"));assertEquals(false,get(restored,"saving"))}
}
